function homeCheckout(){const c=foodStory[storyIndex];return `<section id="om-life-story" class="om-card om-story om-continuous-story" data-playing="false"><h1>Food, connected.</h1><div id="om-story-frame" class="om-story-frame">${proofFallback(storyIndex)}</div><div class="om-story-caption"><h2 id="om-story-title">${e(c.title)}</h2><p id="om-story-copy">${e(c.copy)}</p></div><label class="om-sr" for="om-story-scrub">Explore the food journey</label><input id="om-story-scrub" type="range" min="0" max="6" step=".01" value="0" aria-label="Explore the food journey"><div class="om-journey-stops">${foodStory.map((x,i)=>`<button type="button" data-story-stop="${i}">${e(x.name)}</button>`).join('')}</div><div class="om-story-controls">${b('Back',{id:'om-story-back',variant:'secondary'})}${b('Play story',{id:'om-story-play',variant:'primary'})}${b('Replay',{id:'om-story-replay',variant:'secondary'})}${b('Next',{id:'om-story-next',variant:'secondary'})}</div><div class="om-row om-story-cta">${b('Try the sample kitchen →',{href:url('app'),variant:'primary'})}${b('Sign-in options',{href:url('auth'),variant:'secondary'})}</div><p id="om-story-status" class="om-story-status" role="status">One continuous kitchen · illustrative sample journey · no camera or account access.</p></section>`;}
function stopStory(){cancelAnimationFrame(storyTimer);storyTimer=null;storyTick=0;storyPlaying=false;$('om-story-frame')?.querySelector('video')?.pause();if($('om-story-frame')?._proof)$('om-story-frame')._proof.update(storyPosition,false);const root=$('om-life-story');if(root)root.dataset.playing='false';if($('om-story-play'))$('om-story-play').textContent=matchMedia('(prefers-reduced-motion:reduce)').matches?'Static story':'Play story';}
function proofFallback(i){return `<img src="/asset-family/storyboard-${i}.png?v=P42.2-clean" alt="Original volumetric kitchen scene, static view of chapter ${i+1}" style="width:100%;height:100%;object-fit:contain">`;}
function updateProof(){const frame=$('om-story-frame');if(!frame)return;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;const nativeMode=new URLSearchParams(location.search).get('mode')==='live3d';if(!nativeMode&&!reduced){let video=frame.querySelector('video');if(!video){frame._proof?.dispose();frame._proof=null;frame.innerHTML='<video muted playsinline preload="auto" poster="/asset-family/journey-poster.png?v=P42.2-clean" aria-label="Blender-authored continuous 3D kitchen animatic" style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain" src="/asset-family/journey.mp4?v=P42.2-clean"></video>';video=frame.querySelector('video');video.muted=true;const mediaStarted=performance.now();if(video.requestVideoFrameCallback){const presented=(stamp,meta)=>{if(!frame.isConnected)return;if(!frame.dataset.firstVideoFrameMs)frame.dataset.firstVideoFrameMs=(performance.now()-mediaStarted).toFixed(1);frame.dataset.presentedMediaTime=meta.mediaTime.toFixed(2);frame.dataset.presentedFrames=String(meta.presentedFrames);video.requestVideoFrameCallback(presented);};video.requestVideoFrameCallback(presented);}video.addEventListener('loadeddata',()=>{frame.dataset.mediaReady='true';frame.dataset.mediaDataReadyMs=(performance.now()-mediaStarted).toFixed(1);if(storyPlaying)video.play().catch(()=>{frame.dataset.autoplay='blocked';});});video.addEventListener('ended',()=>{video.currentTime=0;if(storyPlaying)video.play();});}frame.dataset.renderer='Blender-rendered-3D-animatic';frame.dataset.timelineSource='offmenu-journey.blend';if(storyPlaying){if(video.paused&&video.readyState>=2)video.play().catch(()=>{});}else{video.pause();const wanted=Math.min(23.95,storyPosition*4);if(Math.abs(video.currentTime-wanted)>.09)video.currentTime=wanted;}return;}const capable=innerWidth>=900&&!reduced;if(!capable){if(frame._proof){frame._proof.dispose();frame._proof=null;}if(frame.dataset.staticChapter!==String(storyIndex)){frame.innerHTML=proofFallback(storyIndex);frame.dataset.staticChapter=String(storyIndex);}for(const key of ['cameraYaw','glError','renderedFrames','triangles'])delete frame.dataset[key];frame.dataset.chapter=String(storyIndex+1);frame.dataset.renderer=reduced?'static-reduced-motion':'static-lightweight';return;}if(frame._proof){frame._proof.update(storyPosition,storyPlaying);return;}if(frame._proofLoading)return;frame.innerHTML=proofFallback(storyIndex);frame._proofLoading=true;const loadStarted=performance.now();const moduleURL='/asset-family/renderer.js?v=live3d-startup-bounded-4';import(moduleURL).then(({mount})=>{if(!frame.isConnected)return;if(new URLSearchParams(location.search).get('diagnostics')==='1'){const imported=performance.now();const entry=performance.getEntriesByName(new URL(moduleURL,location.href).href).at(-1);frame.dataset.moduleLoad=JSON.stringify({importResolveMs:Number((imported-loadStarted).toFixed(3)),resource:entry?{duration:entry.duration,startTime:entry.startTime,responseStart:entry.responseStart,responseEnd:entry.responseEnd,transferSize:entry.transferSize,encodedBodySize:entry.encodedBodySize,decodedBodySize:entry.decodedBodySize}:null,cacheWarmth:'unknown'});}frame._proof=mount(frame);frame.dataset.importToFirstDrawMs=(performance.now()-loadStarted).toFixed(1);frame._proof.update(storyPosition,storyPlaying);storyTick=performance.now();frame.dataset.storyClockReadyAt=storyTick.toFixed(2);const controls=document.createElement('div');controls.className='om-proof-controls';controls.innerHTML='<span>Original 3D proof</span><button type="button" aria-label="Rotate camera left">↶</button><button type="button" aria-label="Rotate camera right">↷</button>';controls.querySelectorAll('button').forEach((button,i)=>button.onclick=()=>{storyWantsPlay=false;stopStory();frame._proof.rotate(i?.3:-.3);});frame.append(controls);}).catch(error=>{frame.dataset.renderer='static-webgl-unavailable';frame.dataset.renderError=String(error.message);}).finally(()=>{frame._proofLoading=false;});}
function updateStory(){if(!$('om-life-story'))return;const mediaMode=Boolean($('om-story-frame')?.querySelector('video'));storyIndex=Math.min(6,Math.floor(mediaMode?storyPosition*7/6:storyPosition+.12));const c=foodStory[storyIndex],root=$('om-life-story'),caption=root.querySelector('.om-story-caption');root.dataset.playing=String(storyPlaying);updateProof();if(caption.dataset.chapter!==String(storyIndex)){caption.dataset.chapter=String(storyIndex);caption.classList.remove('om-caption-enter');void caption.offsetWidth;caption.classList.add('om-caption-enter');$('om-story-title').textContent=c.title;$('om-story-copy').textContent=c.copy;}const chapterPhase=(mediaMode?storyPosition*7/6:storyPosition)%1;caption.style.opacity=chapterPhase>.72&&chapterPhase<.88?String(1-(chapterPhase-.72)/.16):'1';$('om-story-scrub').value=String(Math.min(6,storyPosition));$('om-story-scrub').setAttribute('aria-valuetext',c.name);root.querySelectorAll('[data-story-stop]').forEach(x=>x.setAttribute('aria-current',String(Number(x.dataset.storyStop)===storyIndex)));$('om-story-back').disabled=storyPosition<=0;$('om-story-next').disabled=storyPosition>=6;$('om-story-play').textContent=matchMedia('(prefers-reduced-motion:reduce)').matches?'Static story':storyPlaying?'Pause':'Play story';}
function runStory(){cancelAnimationFrame(storyTimer);storyTick=performance.now();let lastUpdate=0;const step=()=>{const t=performance.now();if(!storyPlaying||!$('om-life-story')||document.hidden||matchMedia('(prefers-reduced-motion:reduce)').matches)return;if($('om-story-frame')?._proofLoading){storyTick=t;storyTimer=requestAnimationFrame(step);return;}if(t-lastUpdate<66){storyTimer=requestAnimationFrame(step);return;}lastUpdate=t;const dt=storyTick?(t-storyTick):16;storyTick=t;const movie=$('om-story-frame')?.querySelector('video');if(movie){storyPosition=movie.currentTime/4;}else{storyPosition+=dt/4000;if(storyPosition>6.75)storyPosition=0;}updateStory();storyTimer=requestAnimationFrame(step);};storyTimer=requestAnimationFrame(step);}
