function renderAuth(){const state=paramsNow().get('state')||'account';const providers=[['Google','Continuity pending'],['Apple','Catalog · not configured'],['GitHub','Catalog · not configured'],['Microsoft','Catalog · not configured']];return `<div class="om-two om-section om-auth-layout"><section class="om-card om-stack om-auth-sheet"><p class="om-eyebrow">ACCOUNT ACCESS · BETTER AUTH DIRECTION</p><h1>Sign in to OffMenu.</h1><p>Choose a sign-in method. This prototype does not connect to identity providers.</p><div class="om-provider-options om-provider-grid">${providers.map(([name,status])=>`<div class="om-stack-sm">${b(name,{disabled:true,variant:'primary'})}<small class="om-muted">${e(status)}</small></div>`).join('')}</div><div class="om-stack-sm">${b('Email & password',{disabled:true,variant:'secondary'})}<small class="om-muted">Foundation available · disabled by default · not activated</small></div><div class="om-notice"><strong>No live method is available here.</strong><p>Provider choices are an unconnected preview. No credentials, grants or account changes are requested.</p></div><p class="om-muted om-auth-method-note">Google continuity is pending qualification. Additional social names show Better Auth capabilities, not configured or approved OffMenu registrations.</p></section><aside class="om-card om-stack om-auth-sheet"><p class="om-eyebrow">DEMO AVAILABLE · NO SIGN-IN</p><h2>Explore a sample workspace.</h2><p>Try stock, meal planning and shopping with fictional data. Changes stay in this tab.</p>${field('Sample household','<select id="demo-persona"><option>Alex’s everyday kitchen · 2 people</option><option>Sam’s first pantry · 1 person</option></select>','Presentation choices only; no account is created.')}<p id="auth-status" class="om-status" role="status">${state==='error'?'Example error state. No provider call was made.':state==='sent'?'Example invitation state. Nothing was emailed.':'The demo is ready.'}</p>${b('Enter the demo workspace →',{id:'demo-enter',variant:'primary'})}<div class="om-auth-context"><h3>About these choices</h3><p class="om-muted">The Better Auth migration is required. The inspected foundation is unmounted; it does not make these methods live.</p><div class="om-row">${badge('Demo available')}${badge('Providers unconnected')}</div><details><summary>Method evidence & capability catalog</summary><p>Project requirement: <a href="https://github.com/maldous/offmenu/issues/32" target="_blank" rel="noopener">OffMenu issue 32</a>. Foundation supports opt-in email, disabled by default. Additional social methods require separate configuration and qualification.</p><p><a href="https://better-auth.com/docs/authentication/google" target="_blank" rel="noopener">Google</a> · <a href="https://better-auth.com/docs/authentication/github" target="_blank" rel="noopener">GitHub</a> · <a href="https://better-auth.com/docs/authentication/microsoft" target="_blank" rel="noopener">Microsoft</a></p></details></div></aside></div>`;}
function paramsNow(){return new URLSearchParams(location.search);}
