function appNav(){return `<nav class="om-appnav" aria-label="Kitchen navigation">${['today','kitchen','plan','shop','me'].map(v=>`<a data-area="app" data-view="${v}" href="${e(url('app',{view:v}))}" aria-current="${v===view?'page':'false'}">${({today:'✳ Today',kitchen:'▤ Kitchen',plan:'▦ Plan',shop:'◫ Shop',me:'♧ Me'})[v]}</a>`).join('')}</nav>`;}
function renderApp(){const labels={today:['Good food starts here.','A few possibilities from your kitchen.'],kitchen:['A little order. A lot of possibility.','Keep one shelf in view, then build from there.'],plan:['A week with room to breathe.','Simple plans, built around what you have.'],shop:['A little list. A better next meal.','Only the gaps you choose to shop for.'],me:['Make yourself at home.','A demo kitchen that works your way.']};let content='';const state=paramsNow().get('state')||'ready';const stateControl=`<details class="om-state-tools"><summary>Demo state · ${e(state)}</summary><div class="om-reviewbar">${field('Review a state','<select id="review-state">'+['ready','loading','empty','error','offline','recovery'].map(x=>`<option ${x===state?'selected':''}>${x}</option>`).join('')+'</select>')}<p class="om-muted">Simulated states. No network or real saved data changes.</p></div></details>`;if(['loading','empty','error','recovery'].includes(state)){const messages={loading:['Getting the kitchen ready…','This is the loading-state example. Sample stock is unchanged.'],empty:['A little room for possibility.','An empty kitchen starts with one shelf. Your other sample state is retained.'],error:['We couldn’t open this kitchen.','This is an error-state example. Your sample stock is unchanged; you can safely try again.'],recovery:['Pick up where you left off.','This is a recovery-state example: a three-item sample checkout draft is available to review.']};return `${appNav()}${stateControl}<div class="om-card om-stack" ${state==='loading'?'aria-busy="true"':''}><p class="om-eyebrow">${e(state)} / PRESENTATION EXAMPLE</p><h1>${messages[state][0]}</h1><p>${messages[state][1]}</p>${b(state==='error'?'Try again':state==='recovery'?'Review sample draft':state==='empty'?'Explore a sample kitchen':'Show ready state',{id:state==='recovery'?'recover-checkout':'return-ready',variant:'primary'})}${state==='recovery'?b('Discard this sample draft',{id:'return-ready',variant:'secondary'}):''}</div>`;}
 if(view==='today'){const matches=matchMeals(pantry,recipes,2,new Date().toISOString().slice(0,10));content=`<div class="om-grid">${matches.map(r=>card(r.title,`<div class="om-food-display" aria-hidden="true">${r.icon}</div><div class="om-row">${badge(r.status==='ready'?'Ready to cook':'Ingredients to add',r.status==='ready'?'neutral':'accent')}<span>${e(r.time)} · 2 portions</span></div><details><summary>Ingredients & directions</summary><ul>${r.ingredients.map(i=>`<li>${i.quantity} ${e(i.unit)} ${e(i.ingredient)}</li>`).join('')}</ul><ol>${r.instructions.map(i=>`<li>${e(i)}</li>`).join('')}</ol><p class="om-muted">Synthetic recipe. Nutrition unavailable; no matched source profiles.</p></details><div class="om-stack-sm">${b('Add to my plan',{id:'plan-'+r.id})}${r.missing.length?b('Add missing ingredients to Shop',{id:'shop-'+r.id,variant:'secondary'}):''}</div>`)).join('')}</div>`;}
 if(view==='today')content=`<div class="om-dashboard">${content}<aside class="om-kitchen-context">${card('Your kitchen, in context',`<div class="om-row">${badge(pantry.length+' demo foods')}${badge(plan.length+' planned meals')}</div><table class="om-table om-context-table"><caption class="om-sr">Current sample stock in this tab</caption><thead><tr><th>Food</th><th>Stock</th><th>Location</th></tr></thead><tbody>${pantry.map(x=>`<tr><td>${e(x.name)}</td><td class="om-amount">${e(amount(x.quantity))} ${e(x.unit)}</td><td>${e(x.location)}</td></tr>`).join('')}</tbody></table><div class="om-row">${badge(matchMeals(pantry,recipes,2,new Date().toISOString().slice(0,10)).filter(x=>x.status==='ready').length+' recipes ready')}${badge(recipes.length+' sample recipes')}</div><p class="om-muted">Nutrition and current prices: unavailable. Quantities are fictional; source completeness is not established.</p>${b('Open Kitchen →',{href:url('app',{view:'kitchen'}),variant:'secondary'})}`)}</aside></div>`;
 if(view==='kitchen')content=`<div class="om-panes"><section class="om-card om-stack"><div class="om-row om-between"><h2>Your stock</h2>${badge(pantry.length+' '+(pantry.length===1?'item':'items'))}</div>${pantry.length?`<ul class="om-list">${pantry.map(x=>itemRow(x)).join('')}</ul>`:emptyState('Room for something good.','Add your first sample item or try the shelf checkout.')}</section><aside class="om-stack">${card('One shelf. One fresh start.','<p>Put the shelf’s contents on a bench and scan each item back. Nothing changes until you confirm the final receipt.</p>'+b('Try a shelf reset',{id:'reset-shelf',variant:'primary'}))}${card('Just brought groceries home?','<p>Unpack a shop or delivery. This adds items; it does not replace a shelf.</p>'+b('Unpack sample groceries',{id:'unpack',variant:'secondary'}))}${receipt?receiptHTML():''}</aside></div>`;
 if(view==='plan')content=`<div class="om-panes"><section class="om-stack">${plan.length?plan.map((id,i)=>card('Dinner '+(i+1),`<h2>${e(recipes.find(r=>r.id===id).title)}</h2><p>2 planned portions · sample household</p>${b('Remove from plan',{id:'remove-plan-'+i,variant:'secondary'})}`)).join(''):emptyState('An open evening.','Choose a meal from Today to start your plan.')}${b('Find a meal →',{href:url('app',{view:'today'})})}</section><aside class="om-card om-stack"><h2>In context</h2><p class="om-amount">${plan.length} planned ${plan.length===1?'meal':'meals'} · ${plan.length*2} portions</p><p class="om-muted">Nutrition total: unavailable. These sample recipes have no matched nutrition profiles. This is not a nutritionally complete plan.</p>${b('Print this plan',{id:'print-plan',variant:'secondary'})}</aside></div>`;
 if(view==='shop')content=`<div class="om-panes"><section class="om-card om-stack"><h2>Your shopping list</h2>${shopping.length?`<ul class="om-list">${shopping.map((x,i)=>itemRow(x,b('Got it',{id:'got-'+i,variant:'secondary'}))).join('')}</ul>`:emptyState('A little room on your list.','Add missing ingredients from Today, or try unpacking sample groceries.')}<p class="om-muted">Current retailer prices: unavailable. No purchase or provider lookup is made.</p></section><aside class="om-stack">${card('Shopping’s home. Let’s unpack.','<p>Auto-accept sample products, Void a mistake and check the final receipt before adding them.</p>'+b('Unpack sample groceries',{id:'unpack',variant:'primary'}))}${receipt?receiptHTML():''}</aside></div>`;
 if(view==='me')content=`<div class="om-grid">${card('A quieter kitchen.',`<label class="om-check"><input type="checkbox" id="quiet" ${quiet?'checked':''}>Quiet mode</label><p class="om-muted">Static status is always enough. Effects are optional and start off.</p><label class="om-check"><input type="checkbox" id="sound" ${sound?'checked':''} ${quiet?'disabled':''}>Short sound on sample scan</label><label class="om-check"><input type="checkbox" id="vibration" ${vibration?'checked':''} ${quiet||!navigator.vibrate?'disabled':''}>Vibration ${navigator.vibrate?'':'· unavailable here'}</label><label class="om-check"><input type="checkbox" id="spoken" ${spoken?'checked':''} ${quiet||!window.speechSynthesis?'disabled':''}>Spoken sample name ${window.speechSynthesis?'':'· unavailable here'}</label>`)}${card('Room to tap.',`<label class="om-check"><input type="checkbox" id="large" ${large?'checked':''}>Extra-large controls</label><p>Standard controls are at least56px. Extra-large uses64px. Reduced-motion follows your system preference.</p>`)}${card('Your demo, in context.','<p>This example keeps changes in this tab only. Reload starts a fresh sample kitchen. No real account, pantry or dietary history is accessed.</p>'+b('Review sign-in options',{href:url('auth'),variant:'secondary'}))}</div>`;
 return `${stateControl}${state==='offline'?'<div class="om-notice" role="status">Offline-state preview. This sample kitchen works in this tab; no network setting changed. Real cloud sync is not connected.</div><br>':''}<div class="om-row om-between"><div class="om-stack-sm"><p class="om-eyebrow">POST-SIGN-IN WORKSPACE / SAMPLE SESSION</p><h1>${labels[view][0]}</h1><p class="om-muted">${labels[view][1]}</p></div><div class="om-row">${b('▥ Scan / unpack',{id:'quick-scan',variant:'primary'})}${b('+ Add food',{id:'quick-add',variant:'secondary'})}</div></div>${appNav()}<p class="om-status" id="app-status" role="status"></p>${content}`;}
function receiptHTML(){return card('Your final receipt',`<div class="om-receipt om-stack-sm"><p class="om-eyebrow">${receipt.mode==='shelf'?'SHELF RESET':'GROCERIES ADDED'} / SAMPLE</p><h3>A little better stocked.</h3><ul class="om-list">${receipt.items.map(x=>itemRow(x)).join('')}</ul><p>${receipt.items.length} ${receipt.items.length===1?'item':'items'} confirmed · quantities in source units.</p>${b('Print receipt',{id:'print-receipt',variant:'secondary'})}</div>`);}
function feedbackEffect(name){if(quiet)return;try{if(vibration&&navigator.vibrate)navigator.vibrate(30);if(spoken&&window.speechSynthesis)window.speechSynthesis.speak(new SpeechSynthesisUtterance(name));if(sound){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){const a=new Audio(),o=a.createOscillator(),g=a.createGain();g.gain.value=.035;o.frequency.value=660;o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+.06);o.onended=()=>a.close();}}}catch{} }
function checkoutDialog(nextMode){mode=nextMode;checkout=[];scanIndex=0;reviewed=false;checkoutLocation='Pantry / Shelf 1';drawCheckout();}
function drawCheckout(){const oldBody=$('om-dialog-body');if(oldBody){viewportPagers.get(oldBody)?.dispose();viewportPagers.delete(oldBody);}const body=`<p class="om-eyebrow">${mode==='shelf'?'ONE SHELF / REPLACE AFTER REVIEW':'SHOPPING / ADD TO STOCK'}</p><p>${mode==='shelf'?'Only '+e(checkoutLocation)+' will be replaced after final confirmation. Every other location stays in place.':'These sample groceries add to '+e(checkoutLocation)+'. Existing stock is kept.'}</p>${field(mode==='shelf'?'Choose the shelf to reset':'Unpack into','<select id="checkout-location">'+['Pantry / Shelf 1','Fridge / Shelf 1','Freezer / Drawer 1'].map(x=>`<option ${x===checkoutLocation?'selected':''}>${e(x)}</option>`).join('')+'</select>','Location applies to this receipt. No stock changes before confirmation.')}<div class="om-notice">Simulated scanner. No camera opens; each press presents a different fictional item and auto-accepts it.</div><p class="om-status" id="scan-status" role="status">${checkout.length?checkout.length+' accepted · ready for the next item':'Your checkout is ready.'}</p>${!reviewed?b('Present a sample item →',{id:'present-item',variant:'primary'}):badge('FINAL RECEIPT / REVIEW BEFORE SAVING','accent')}<ul class="om-list">${checkout.map((x,i)=>itemRow(x,b('Void',{id:'void-'+i,variant:'secondary'}))).join('')}</ul><div class="om-row">${reviewed?b(mode==='shelf'?'Confirm: replace this shelf':'Confirm: add groceries',{id:'confirm-receipt',variant:'primary',disabled:!checkout.length}):b('Review final receipt',{id:'final-receipt',disabled:!checkout.length})}${b('Cancel checkout',{id:'cancel-checkout',variant:'secondary'})}</div><p class="om-muted">All changes stay in this playground tab. No prices or nutrition are inferred.</p>`;const d=$('om-dialog');if(d.open){$('om-dialog-body').innerHTML=body;}else openDialog(mode==='shelf'?'One shelf, fresh eyes.':'Let’s unpack something good.',body);
 if($('checkout-location'))$('checkout-location').onchange=ev=>{checkoutLocation=ev.target.value;checkout=checkout.map(x=>({...x,location:checkoutLocation}));reviewed=false;drawCheckout();$('checkout-location').focus();};
 if($('present-item'))$('present-item').onclick=()=>{const samples=[{...seed[0],quantity:250},{...seed[2],quantity:6},{...seed[3],quantity:500}];const sample={...samples[scanIndex++%samples.length],id:'receipt-'+scanIndex,location:checkoutLocation};checkout.push(sample);feedbackEffect(sample.name);drawCheckout();announce(sample.name+' accepted. '+checkout.length+' items.');$('present-item')?.focus();};
 checkout.forEach((x,i)=>$('void-'+i).onclick=()=>{checkout.splice(i,1);drawCheckout();announce('Item voided.');});
 if($('final-receipt'))$('final-receipt').onclick=()=>{reviewed=true;drawCheckout();$('confirm-receipt').focus();};
 if($('confirm-receipt'))$('confirm-receipt').onclick=()=>{if(!checkout.length)return;const items=checkout.map((x,i)=>({...x,id:'confirmed-'+Date.now()+'-'+i,location:checkoutLocation}));pantry=mode==='shelf'?[...pantry.filter(x=>x.location!==checkoutLocation),...items]:[...pantry,...items];receipt={mode,location:checkoutLocation,items:structuredClone(items)};$('om-dialog').close();view='kitchen';history.replaceState(null,'',url('app',{view}));render();announce('Final receipt confirmed. '+items.length+' items saved in this demo tab.');};$('cancel-checkout').onclick=()=>d.close();window.dispatchEvent(new Event('offmenu-dialog-content'));}
function addFood(){openDialog('Add a little possibility.',`<form id="add-food" class="om-stack">${field('Food name','<input id="food-name" maxlength="100" required placeholder="e.g. Brown rice">')}${field('Quantity','<input id="food-quantity" type="number" inputmode="decimal" min="0.001" step="any" required placeholder="250">')}${field('Unit','<select id="food-unit"><option>g</option><option>ml</option><option>count</option></select>')}<p class="om-muted">Manual sample entry only. No product identity, nutrition or price is inferred.</p><button class="om-btn" data-variant="accent" type="submit">Add to the demo pantry</button></form>`);$('add-food').onsubmit=ev=>{ev.preventDefault();if(!$('food-name').value.trim()){$('food-name').setCustomValidity('Enter a food name.');$('food-name').reportValidity();return;}$('food-name').setCustomValidity('');pantry.push({id:'manual-'+Date.now(),name:$('food-name').value.trim(),ingredient:$('food-name').value.trim().toLowerCase(),quantity:Number($('food-quantity').value),unit:$('food-unit').value,location:'Pantry / Shelf 1',icon:'🥣',needsReview:true});$('om-dialog').close();view='kitchen';history.replaceState(null,'',url('app',{view}));render();announce('Food added to this demo tab.');};}
function renderCatalog(){const fixture=paramsNow().get('data')||'demo';const items=fixture==='empty'?[]:fixture==='one'?[seed[0]]:fixture==='worst'?[{...seed[0],name:'Aleksandra’s long-grain wholegrain rice from the family pantry',quantity:.125},{...seed[1],name:'ข้าวหอมมะลิ · أرز طويل الحبة · 米飯',quantity:null},{...seed[2],name:'Jo',quantity:1000000}]:seed;return `<div class="om-stack"><p class="om-eyebrow">OFFMENU SYSTEM1.0 / COMPONENT CATALOG</p><h1>One language.<br>Every food moment.</h1><p class="om-large-copy">The landing, sign-in and application use these same tokens and native components. Switch themes above; inspect states below.</p><div class="om-reviewbar">${field('Fixture','<select id="catalog-data">'+['demo','worst','empty','one'].map(v=>`<option ${fixture===v?'selected':''}>${v}</option>`).join('')+'</select>')}${field('Direction','<select id="catalog-direction"><option value="ltr">Left to right</option><option value="rtl">Right to left</option></select>')}</div><section class="om-card om-stack"><h2>Brand & semantic colours</h2><div class="om-swatches"><div class="om-swatch" style="background:var(--om-bg);color:var(--om-ink)">Canvas / ink<br><code>--om-bg / --om-ink</code></div><div class="om-swatch" style="background:var(--om-action);color:var(--om-on-action)">Primary action<br><code>--om-action</code></div><div class="om-swatch" style="background:var(--om-accent);color:var(--om-on-accent)">Warm status accent<br><code>--om-accent</code></div></div></section><div class="om-grid">${card('Buttons & focus',`<div class="om-stack-sm">${b('Primary action')}${b('Secondary action',{variant:'secondary'})}${b('Accent action',{variant:'primary'})}${b('Unavailable action',{disabled:true})}${b('Open native dialog',{id:'catalog-dialog',variant:'secondary'})}</div><code class="om-code">button(label, {variant, href, id, disabled})</code>`)}${card('Forms & status',`${field('A visible label','<input placeholder="Your sample label" maxlength="100">','A hint stays linked inside the label.')}<div class="om-notice" role="status">A real unknown stays unknown.</div>${badge('Needs review','accent')}<code class="om-code">field(label, controlHTML, hint)</code>`)}${card('Type & spacing',`<p class="om-eyebrow">EYEBROW / .75REM</p><h2>Food, with context.</h2><p>Body1rem, line-height1.55. Humanist sans display follows the retained dark OffMenu system; italic is limited to a short warm emphasis. No external font call.</p><p class="om-muted">Spacing:4 /8 /12 /16 /24 /32 /48 /64px.</p><code class="om-code">--om-space-*\n--om-title / --om-hero</code>`)}</div><section class="om-card om-stack"><h2>Stock rows / ${items.length} ${items.length===1?'item':'items'}</h2>${items.length?`<ul class="om-list">${items.map(x=>itemRow(x)).join('')}</ul>`:emptyState('A little room for possibility.','Empty states give one clear next step, without inventing data.')}</section><section class="om-card om-stack"><h2>Interaction contract</h2><p>Native button and link semantics. Minimum56px targets,16px inputs, visible keyboard focus. Dialog uses Escape, a labelled heading and focus return. No required motion; only short pointer press feedback. Quiet and reduced motion remove movement. Hover is capability-gated.</p><code class="om-code">card(title, trustedBodyHTML, {feature})\nbadge(text, tone)\nemptyState(title, body)\nopenDialog(title, trustedBodyHTML)\nsetTheme('light' | 'dark' | 'system')</code><p>Repository entrypoint: <code>docs/ui/design-system/README.md</code>. Shared implementation: <code>public/offmenu-system.css</code> and <code>public/offmenu-system.js</code>.</p></section></div>`;}
function review(){const ranked=[...scores].sort((a,b)=>b[1].score-a[1].score);openDialog('Your eye makes this better.',`<form id="review-form" class="om-stack"><p>Reviewing: <strong>${e(area)}</strong> / ${VERSION}. Notes stay in this tab; nothing is sent.</p><fieldset><legend>How clear and comfortable is this screen?</legend><div class="om-rating">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="score" value="${n}" ${scores.get(area)?.score===n?'checked':''} required>${n}</label>`).join('')}</div></fieldset>${field('What should change?','<textarea id="review-notes" maxlength="2000" placeholder="What felt clear? What slowed you down?"></textarea>')}<button class="om-btn" type="submit">Save this tab’s score</button><p class="om-status" id="review-saved" role="status"></p><div><h3>Your current ranking</h3><div id="ranked-scores">${ranked.length?'<ol>'+ranked.map(([a,x])=>`<li>${e(a)} · ${x.score}/5</li>`).join('')+'</ol>':'<p>No scores yet.</p>'}</div></div>${b('Download my feedback',{id:'download-feedback',variant:'secondary',disabled:!ranked.length})}</form>`);$('review-notes').value=scores.get(area)?.notes||'';$('review-form').onsubmit=ev=>{ev.preventDefault();scores.set(area,{score:Number(new FormData(ev.target).get('score')),notes:$('review-notes').value,version:VERSION});$('review-saved').textContent='Score saved in this tab. Ranking updated.';$('ranked-scores').innerHTML='<ol>'+[...scores].sort((a,b)=>b[1].score-a[1].score).map(([a,x])=>`<li>${e(a)} · ${x.score}/5</li>`).join('')+'</ol>';$('download-feedback').disabled=false;announce('Score saved.');};$('download-feedback').onclick=()=>{const blob=new Blob([JSON.stringify({version:VERSION,scores:Object.fromEntries(scores)},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='offmenu-P41-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};}
function bind(){wireNavigation();bindStory();if($('review-state'))$('review-state').onchange=ev=>{history.replaceState(null,'',url('app',{view,state:ev.target.value}));render();};if($('return-ready'))$('return-ready').onclick=()=>{history.replaceState(null,'',url('app',{view}));render();announce('Ready sample state restored.');};if($('recover-checkout'))$('recover-checkout').onclick=()=>{mode='shopping';checkout=structuredClone(seed.slice(0,3));reviewed=false;drawCheckout();};if($('demo-enter'))$('demo-enter').onclick=()=>navigate('app');if($('quick-scan'))$('quick-scan').onclick=()=>checkoutDialog('shopping');if($('quick-add'))$('quick-add').onclick=addFood;if($('reset-shelf'))$('reset-shelf').onclick=()=>checkoutDialog('shelf');if($('unpack'))$('unpack').onclick=()=>checkoutDialog('shopping');if($('print-plan'))$('print-plan').onclick=()=>window.print();if($('print-receipt'))$('print-receipt').onclick=()=>window.print();
 for(const r of recipes){if($('plan-'+r.id))$('plan-'+r.id).onclick=()=>{plan.push(r.id);$('app-status').textContent=r.title+' added to your plan.';announce('Meal added to plan.');};if($('shop-'+r.id))$('shop-'+r.id).onclick=()=>{const m=matchMeals(pantry,[r],2,new Date().toISOString().slice(0,10))[0];for(const x of m.missing)if(!shopping.some(y=>y.ingredient===x.ingredient))shopping.push({...x,name:x.ingredient,icon:'🍅'});$('app-status').textContent='Missing measured ingredients added to Shop.';announce('Shopping list updated.');};}
 plan.forEach((x,i)=>{if($('remove-plan-'+i))$('remove-plan-'+i).onclick=()=>{plan.splice(i,1);render();};});shopping.forEach((x,i)=>{if($('got-'+i))$('got-'+i).onclick=()=>{shopping.splice(i,1);render();announce('Shopping item checked off.');};});
 if($('quiet'))$('quiet').onchange=ev=>{quiet=ev.target.checked;document.documentElement.dataset.quiet=String(quiet);if(quiet){sound=vibration=spoken=false;}render();};for(const name of ['sound','vibration','spoken'])if($(name))$(name).onchange=ev=>{if(name==='sound')sound=ev.target.checked;if(name==='vibration')vibration=ev.target.checked;if(name==='spoken')spoken=ev.target.checked;};if($('large'))$('large').onchange=ev=>{large=ev.target.checked;document.body.classList.toggle('om-large',large);};
 if($('catalog-data'))$('catalog-data').onchange=ev=>{history.replaceState(null,'',url('components',{data:ev.target.value}));render();};if($('catalog-direction'))$('catalog-direction').onchange=ev=>{$('review-main').dir=ev.target.value;};if($('catalog-dialog'))$('catalog-dialog').onclick=()=>openDialog('A native dialog.',`<p>Escape closes this dialog. Focus returns to the opening button. Content remains selectable.</p>${field('Sample note','<textarea maxlength="100" placeholder="Try keyboard navigation"></textarea>')}`);}
function rationale(){const copy={landing:'The meal outcome leads. The retained dark teal/blue humanist system and product-tour artwork restore OffMenu identity. The home checkout keeps the playful register and receipt. Shelf-reset and shopping consequences are explained before entry. The illustration is static, so repeat visits are immediate.',auth:'The demo and account design are visibly different. Native labelled controls,56px targets and focus outlines support keyboard and touch. Account actions are inert; no credential fields or pretend provider connection.',app:'Today leads the five-task hierarchy. Shared stock rows keep names, quantities and units readable. Frequent checkout actions update immediately; quiet mode uses static status, and native dialogs support Escape and focus return. Unknown nutrition is not zero.',components:'Every example uses the same CSS tokens and component API. Full-width density tokens reveal a desktop task rail and extra kitchen context; text measure and safe areas stay bounded. Theme selection resolves semantic colours; RTL and worst-case fixtures exercise the same components. No framework or external store.'};return `<details class="om-card om-section"><summary>Review rationale · guidance applied here</summary><div class="om-stack-sm"><p>${copy[area]}</p><p class="om-muted">Across all areas:4–64px spacing scale, at least16px inputs, shared56px controls, capability-gated hover and only120ms pointer press feedback. Keyboard, quiet and reduced-motion actions use no movement. Physical-phone feel and screen-reader announcements remain for human review.</p><a href="${e(url('components'))}">Inspect the shared system →</a></div></details>`;}
function render(){stopStory();viewportPagers.get($('review-main'))?.dispose();viewportPagers.delete($('review-main'));header();$('layout-direction').value=paramsNow().get('dir')==='rtl'?'rtl':'ltr';$('review-main').dir=$('layout-direction').value;$('review-main').dataset.area=area;$('review-main').innerHTML=area==='landing'?renderLanding():area==='auth'?renderAuth():area==='components'?renderCatalog():renderApp();if(area!=='landing')$('review-main').insertAdjacentHTML('beforeend',rationale());document.body.classList.toggle('om-large',large);document.documentElement.dataset.quiet=String(quiet);bind();requestAnimationFrame(fitScreen);}
// Viewport pagination preserves original DOM nodes/listeners and keeps every page connected.
const viewportPagers=new WeakMap();
function installViewportPager(container,controls,{dialog=false}={}){
 const existing=viewportPagers.get(container);if(existing)existing.dispose();
 const roots=[...container.childNodes],relations=[...container.querySelectorAll('*')].map(n=>[n,[...n.childNodes]]);
 let page=0,pages=[],busy=false;
 const stage=document.createElement('div');stage.className='om-page-stage';
 const stash=document.createElement('div');stash.hidden=true;
 const previous=document.createElement('button'),next=document.createElement('button'),status=document.createElement('span');
 previous.type=next.type='button';previous.className=next.className='om-btn';previous.textContent='←';next.textContent='→';previous.setAttribute('aria-label',dialog?'Previous dialog page':'Previous screen page');next.setAttribute('aria-label',dialog?'Next dialog page':'Next screen page');status.setAttribute('role','status');status.className='om-page-number';
 controls.replaceChildren(previous,status,next);
 const fits=()=>stage.scrollHeight<=stage.clientHeight+1&&stage.scrollWidth<=stage.clientWidth+1;
 function show(index,focus=false){
  page=Math.max(0,Math.min(index,pages.length-1));for(const child of [...stage.children])stash.append(child);
  stage.replaceChildren(...pages[page]);previous.disabled=page===0;next.disabled=page===pages.length-1;status.textContent=(page+1)+' / '+pages.length;status.setAttribute('aria-label','Page '+(page+1)+' of '+pages.length);
  if(focus){stage.tabIndex=-1;stage.focus({preventScroll:true});}
 }
 function fragment(parent,child,index){const wrapper=parent.cloneNode(false);if(index)wrapper.removeAttribute('id');wrapper.classList.add('om-page-fragment');wrapper.append(child);return wrapper;}
 function reflow(){
  if(busy||!container.isConnected)return;busy=true;container.style.setProperty('--om-available-height',container.clientHeight+'px');
  const active=document.activeElement,old=page;
  for(const [parent,children]of relations)parent.replaceChildren(...children);
  container.replaceChildren(stage,stash);stage.replaceChildren();stash.replaceChildren();pages=[];
  let current=[],queue=roots.filter(n=>n.nodeType===1||n.textContent.trim());let blocked=false;
  const finish=()=>{if(current.length){pages.push(current);for(const n of current)stash.append(n);current=[];}};
  while(queue.length){let node=queue.shift();if(node.nodeType!==1){const text=document.createElement('p');text.textContent=node.textContent;node=text;}
   stage.append(node);
   if(fits()){current.push(node);continue;}
   node.remove();if(current.length&&node.matches('.om-dashboard,.om-grid,.om-panes')&&node.children.length>1){queue.unshift(...node.children);continue;}if(current.length){finish();queue.unshift(node);continue;}
   const children=[...node.childNodes].filter(n=>n.nodeType===1||n.textContent.trim());
   if(children.length>1&&!node.matches('button,a,input,select,textarea,label,summary,svg')){queue.unshift(...children.map((child,i)=>fragment(node,child,i)));continue;}
   if(children.length===1&&children[0].nodeType===1&&!node.matches('button,a,input,select,textarea,label,summary,svg')){queue.unshift(fragment(node,children[0],0));const only=queue.shift();const child=only.firstElementChild;if(child){queue.unshift(child);continue;}}
   const words=node.textContent.trim().split(/\s+/);
   if(words.length>1&&!node.matches('button,a,input,select,textarea,label,summary,svg')){const mid=Math.ceil(words.length/2);queue.unshift(...[words.slice(0,mid),words.slice(mid)].filter(x=>x.length).map((part,i)=>{const x=node.cloneNode(false);if(i)x.removeAttribute('id');x.classList.add('om-page-fragment');x.textContent=part.join(' ');return x;}));continue;}
   // A fixed-size native control cannot always fit after zoom/keyboard reduces usable height.
   const conflict=document.createElement('div');conflict.className='om-fit-conflict';conflict.setAttribute('role','alert');conflict.textContent='This viewport cannot fit the next control with the fixed header and footer. Dismiss the keyboard, rotate the screen or enlarge the viewport. This is a layout conflict; content has not been discarded.';
   const holder=document.createElement('div');holder.hidden=true;holder.append(node);stash.append(holder);pages.push([conflict]);blocked=true;
  }
  finish();if(!pages.length)pages=[[]];container.dataset.fitConflict=String(blocked);
  let wanted=Math.min(old,pages.length-1);if(active&&active!==document.body){const at=pages.findIndex(xs=>xs.some(x=>x===active||x.contains(active)));if(at>=0)wanted=at;}
  show(wanted);if(area==='landing')updateStory();if(active?.isConnected&&stage.contains(active))active.focus({preventScroll:true});busy=false;
 }
 previous.onclick=()=>show(page-1,true);next.onclick=()=>show(page+1,true);
 const resize=()=>requestAnimationFrame(reflow);window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);
 viewportPagers.set(container,{dispose(){window.removeEventListener('resize',resize);window.visualViewport?.removeEventListener('resize',resize);for(const [parent,children]of relations)parent.replaceChildren(...children);container.replaceChildren(...roots);},reflow});
 reflow();
}
function fitScreen(){if(area==='landing'){document.getElementById('om-page-controls')?.remove();$('review-main').style.setProperty('--om-available-height',$('review-main').clientHeight+'px');updateStory();return;}let controls=document.getElementById('om-page-controls');if(!controls){controls=document.createElement('nav');controls.id='om-page-controls';controls.setAttribute('aria-label','Screen pages');document.querySelector('.om-footer').append(controls);}installViewportPager($('review-main'),controls);}
function fitDialog(){const d=$('om-dialog');if(!d.open)return;let controls=d.querySelector('.om-dialog-pages');if(!controls){controls=document.createElement('nav');controls.className='om-dialog-pages';controls.setAttribute('aria-label','Dialog pages');d.append(controls);}installViewportPager($('om-dialog-body'),controls,{dialog:true});}
window.addEventListener('offmenu-dialog-content',()=>requestAnimationFrame(fitDialog));

document.addEventListener('visibilitychange',()=>{if(document.hidden)stopStory();else{const root=$('om-life-story');if(root){const r=root.getBoundingClientRect();if(r.height>0&&r.bottom>0&&r.top<document.documentElement.clientHeight)startStory();}}});
$('layout-direction').onchange=ev=>{const p=paramsNow();p.set('dir',ev.target.value);history.replaceState(null,'',location.pathname+'?'+p);render();};$('theme').onchange=ev=>{theme=ev.target.value;setTheme(theme);const p=paramsNow();p.set('theme',theme);history.replaceState(null,'',location.pathname+'?'+p);render();};matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(theme==='system'){setTheme(theme);render();}});$('review-open').onclick=review;window.addEventListener('popstate',()=>{const p=paramsNow();area=areas.includes(p.get('area'))?p.get('area'):'landing';view=['today','kitchen','plan','shop','me'].includes(p.get('view'))?p.get('view'):'today';theme=['dark','light','system'].includes(p.get('theme'))?p.get('theme'):'dark';setTheme(theme);render();});setTheme(theme);{const canonical=paramsNow();canonical.set('theme',theme);history.replaceState(null,'',location.pathname+'?'+canonical);}render();

window.addEventListener('resize',()=>{if(area==='landing')requestAnimationFrame(()=>{const main=$('review-main');main.style.setProperty('--om-available-height',main.clientHeight+'px');updateStory();});});
